#include <cstdlib>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include "config.hpp"
#include "driver.hpp"
#include "engine.hpp"
#include "rules.hpp"
#include "warnings.hpp"

#if defined(_WIN32)
#include <windows.h>
#elif defined(__APPLE__)
#include <mach-o/dyld.h>
#endif

namespace {
	namespace tidy = blitz::tidy;

	std::filesystem::path executable_path()
	{
#if defined(_WIN32)
		wchar_t buffer[32768];
		DWORD   length = GetModuleFileNameW(nullptr, buffer, DWORD(std::size(buffer)));
		return std::filesystem::path(std::wstring(buffer, length));
#elif defined(__APPLE__)
		char     buffer[4096];
		uint32_t size = sizeof(buffer);
		if (_NSGetExecutablePath(buffer, &size) == 0) {
			return std::filesystem::weakly_canonical(buffer);
		}
		return {};
#else
		std::error_code ec;
		return std::filesystem::read_symlink("/proc/self/exe", ec);
#endif
	}

	// The same userlibs as blitzcc: $BLITZLLVM_USERLIBS, else the one of the installation next to the executable.
	std::filesystem::path find_userlibs()
	{
		if (const char* env = std::getenv("BLITZLLVM_USERLIBS"); env && *env) {
			return env;
		}
		auto bin_dir = executable_path().parent_path();
		for (auto const& candidate : { bin_dir / ".." / "userlibs", bin_dir / "userlibs", bin_dir / ".." / "share" / "blitzllvm" / "userlibs" }) {
			if (std::filesystem::is_directory(candidate)) {
				return std::filesystem::weakly_canonical(candidate);
			}
		}
		return {};
	}

	void list_rules()
	{
		std::cout << "Rules (the name of each is also the name of the warning of blitzcc that it is built on):\n\n";
		for (auto const& rule : tidy::all_rules()) {
			std::cout << "  " << rule.name << "  [default: " << tidy::to_string(rule.default_mode) << (rule.fixable ? "" : ", report only") << "]\n";
			std::cout << "      " << blitz::find_warning(rule.name).description << "\n";
			if (rule.fixable) {
				std::cout << "      Fix: " << rule.fix << "\n";
				if (*rule.unsafe) {
					std::cout << "      Needs \"unsafe\": " << rule.unsafe << "\n";
				}
			}
		}
	}

	const char* help = R"(Settings (as --name=value, or name = value in the configuration file):
  <rule>=off|report|fix   What happens with the findings of a rule, see --rules. Without a value: fix.
  default=off|report|fix  The mode of every rule that is not set.
  unsafe                  Also apply the fixes that can change the program (--unsafe, "unsafe": true).
  max_passes=N            The file is compiled and fixed up to N times (default 20).
  userlibs_dir=DIR        Where the userlibs are, like --userlibs-dir of blitzcc.

Rules are the warnings of blitzcc. Every fix is checked by compiling the result, and a fix that does not compile is left out.
The configuration file is JSON ({ "unsafe": false, "implicit_variable": "report" }) or lines of "name = value". Use --rules to list the rules.
)";

	std::string print_config(blitz::tools::settings const& values)
	{
		tidy::config cfg;
		cfg.apply(values);
		std::string out;
		for (auto const& rule : tidy::all_rules()) {
			out += std::string(rule.name) + " = " + tidy::to_string(cfg.mode_of(rule.name)) + "\n";
		}
		out += std::string("unsafe = ") + (cfg.unsafe ? "true" : "false") + "\nmax_passes = " + std::to_string(cfg.max_passes) + "\n";
		return out;
	}

	std::string process(std::string const& text, blitz::tools::settings const& values, std::string const& name)
	{
		tidy::config cfg;
		cfg.apply(values);
		// The compiler needs a place for the file, which stdin does not have: pretend it is in the current directory.
		cfg.file = (name == "<stdin>") ? std::filesystem::current_path() / "stdin.bb" : std::filesystem::path(name);
		if (cfg.userlibs_dir.empty()) {
			cfg.userlibs_dir = find_userlibs();
		}
		auto result = tidy::run(text, cfg);
		if (result.failed) {
			throw std::runtime_error("can't be checked: " + result.error);
		}
		for (auto const& r : result.reports) {
			std::cerr << name << ":" << r.line << ":" << r.column << ": warning: " << r.message << " [blitz-tidy:" << r.rule << "]\n";
			if (!r.note.empty()) {
				std::cerr << "  note: " << r.note << "\n";
			}
		}
		return result.text;
	}
} // namespace

int main(int argc, char** argv)
{
	for (int i = 1; i < argc; i++) {
		if (std::strcmp(argv[i], "--rules") == 0) {
			list_rules();
			return 0;
		}
	}
	blitz::tools::driver tool;
	tool.name         = "blitz-tidy";
	tool.version      = BLITZLLVM_VERSION;
	tool.summary      = "fixes common mistakes in Blitz source files (see --rules)";
	tool.config_names = { ".blitz-tidy", "blitz-tidy.json" };
	tool.options_help = help;
	tool.process      = process;
	tool.print_config = print_config;
	return blitz::tools::run(tool, argc, argv);
}
